const KW=['async remote','asynchronous remote','worldwide remote','global remote','work from anywhere','remote data analyst','remote data scientist','remote ai marketing','remote marketing analyst','remote growth analyst','remote bi analyst','remote automation','remote ai workflow','data analyst','data scientist','business intelligence','bi analyst','marketing analyst','performance marketing','growth analyst','ai marketing','ai automation','martech','growth hacker','analytics engineer','product analyst','junior data scientist'];
return $input.all().filter(item=>{
  const t=[item.json.job_title,item.json.description,item.json.tags,item.json.location_text].join(' ').toLowerCase();
  return KW.some(k=>t.includes(k));
});

const existing=$('Read Existing Jobs').all();
const existUrls=new Set(existing.map(i=>i.json.job_url).filter(Boolean));
const existKeys=new Set(existing.map(i=>`${(i.json.company||'').toLowerCase()}|${(i.json.job_title||'').toLowerCase()}`).filter(Boolean));
const newJobs=$('Keyword Pre-Filter').all();
return newJobs.filter(item=>{
  const url=item.json.job_url;
  const key=`${(item.json.company||'').toLowerCase()}|${(item.json.job_title||'').toLowerCase()}`;
  return !existUrls.has(url)&&!existKeys.has(key);
});

const REJECT=['us only','usa only','united states only','canada only','uk only','eu only','europe only','australia only','must be based in','must live in','must be authorized to work','local work permit required','hybrid','on-site','onsite','office required','remote within','fixed us hours','fixed eu hours','us residents only','north america only','emea only','latin america only','must relocate'];
const KEEP=['worldwide','work from anywhere','global remote','anywhere','apac','international contractor','contractor role','b2b contractor','deel','remote.com','oyster','eor','remote first','distributed team','hires internationally','global team','all timezones'];
return $input.all().filter(item=>{
  const t=[item.json.description,item.json.location_text,item.json.tags].join(' ').toLowerCase();
  if(REJECT.some(p=>t.includes(p)))return false;
  return true;
}).map(item=>{
  const t=[item.json.description,item.json.location_text,item.json.tags].join(' ').toLowerCase();
  return{...item,json:{...item.json,has_positive_signal:KEEP.some(p=>t.includes(p))}};
});

return $input.all().map(item=>({
  ...item,
  json:{
    ...item.json,
    ai_prompt:`You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

REJECT if:
- Requires living in US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote-within-one-country only
- Requires fixed working hours that force Jerry to work midnight in Taiwan (US daytime hours)

KEEP if:
- Says worldwide remote, work from anywhere, global remote, APAC remote
- Allows international contractors
- Hires through EOR, Deel, Remote.com, Oyster, or contractor agreement
- Accepts people based anywhere

Return ONLY valid JSON:
{"taiwan_eligible":"yes/no/unclear","reason":"short reason","location_risk":"low/medium/high","timezone_risk":"low/medium/high","contractor_possible":"yes/no/unclear","decision":"keep/reject/manual_check"}

Job title: ${item.json.job_title}
Company: ${item.json.company}
Location text: ${item.json.location_text}
Description: ${(item.json.description||'').substring(0,1500)}`
  }
}));

return $input.all().map(item=>{
  let aiResult={};
  try{
    const content=item.json.choices&&item.json.choices[0]&&item.json.choices[0].message&&item.json.choices[0].message.content;
    if(content)aiResult=JSON.parse(content);
  }catch(e){aiResult={taiwan_eligible:'unclear',reason:'parse error',location_risk:'medium',timezone_risk:'medium',contractor_possible:'unclear',decision:'manual_check'};}
  const prev=$('Build AI Prompt').item;
  return{
    json:{
      ...(prev?prev.json:{}),
      ai_result:aiResult,
      taiwan_eligible:aiResult.taiwan_eligible||'unclear',
      taiwan_reason:aiResult.reason||'',
      location_risk:aiResult.location_risk||'medium',
      timezone_risk:aiResult.timezone_risk||'medium',
      contractor_possible:aiResult.contractor_possible||'unclear',
      ai_decision:aiResult.decision||'manual_check'
    }
  };
});

const ASYNC_GOOD=['async','asynchronous','flexible hours','flexible schedule','distributed team','remote first','low meeting','work across time zones','no meetings','written communication','document-first','overlap not required','your own schedule'];
const SYNC_BAD=['strict 9 to 5','fixed us hours','fixed est','fixed pst','fixed cet','daily live calls required','must overlap full business day','must be available 9am-5pm est','core hours required in us','required to work us hours'];
return $input.all().filter(item=>{
  const t=[item.json.description||'',item.json.tags||''].join(' ').toLowerCase();
  return !SYNC_BAD.some(s=>t.includes(s));
}).map(item=>{
  const t=[item.json.description||'',item.json.tags||''].join(' ').toLowerCase();
  const score=ASYNC_GOOD.filter(s=>t.includes(s)).length;
  let level='unknown';
  if(score>=3)level='high';
  else if(score>=1)level='medium';
  return{...item,json:{...item.json,async_level:level,async_keyword_count:score}};
});

const HIGH=['data analyst','data scientist','business intelligence','bi analyst','marketing analyst','performance marketing','growth analyst','growth hacker','ai marketing','ai automation','ai workflow','martech analyst','analytics engineer','marketing data','product analyst','junior data scientist','creative strategist with data'];
const MED=['digital marketing','seo','content analyst','operations analyst','automation engineer','no-code','low-code','crm analyst','email marketing','paid media','ppc','conversion optimization','revenue operations','demand generation'];
const results=[];
for(const item of $input.all()){
  const t=[item.json.job_title,item.json.description,item.json.tags].join(' ').toLowerCase();
  const te=item.json.taiwan_eligible||'unclear';
  const lr=item.json.location_risk||'medium';
  // Taiwan score (0-40)
  let ts=0;
  if(te==='yes'){ts=lr==='low'?40:lr==='medium'?30:20;}
  else if(te==='unclear'){ts=item.json.has_positive_signal?20:10;}
  else{results.push({...item,json:{...item.json,score:0,reject_reason:'AI: Taiwan ineligible'}});continue;}
  // Async score (0-25)
  const al=item.json.async_level||'unknown';
  const as2=al==='high'?25:al==='medium'?20:item.json.async_keyword_count>0?15:10;
  // Role score (0-25)
  let rs=5,rc='other';
  if(HIGH.some(r=>t.includes(r))){rs=25;rc='high_fit';}
  else if(MED.some(r=>t.includes(r))){rs=15;rc='medium_fit';}
  // Salary score (0-10)
  const sal=item.json.salary||'';
  const nums=(sal.match(/\d[\d,]*/g)||[]).map(n=>parseInt(n.replace(/,/g,'')));
  const maxN=nums.length?Math.max(...nums):0;
  const ss=maxN>=60000||maxN>=5000?10:maxN>=36000||maxN>=3000?7:sal?5:0;
  const score=ts+as2+rs+ss;
  const reasons=[];
  if(te==='yes')reasons.push('Taiwan eligible');
  if(al==='high')reasons.push('fully async');
  if(rc==='high_fit')reasons.push('strong role match');
  if(sal)reasons.push('salary listed');
  results.push({...item,json:{
    ...item.json,score,taiwan_score:ts,async_score:as2,role_score:rs,salary_score:ss,
    role_category:rc,why_good_fit:reasons.join('; '),
    reject_reason:score<70?`Score ${score} below 70`:''
  }});
}
return results;

const all=$input.all().sort((a,b)=>(b.json.score||0)-(a.json.score||0));
const kept=all.filter(i=>(i.json.score||0)>=70);
const rejected=all.filter(i=>(i.json.score||0)<70);
const rejUS=rejected.filter(i=>(i.json.reject_reason||'').toLowerCase().includes('us only')||i.json.taiwan_eligible==='no').length;
const rejHybrid=rejected.filter(i=>(i.json.reject_reason||'').toLowerCase().includes('hybrid')).length;
const rejTZ=rejected.filter(i=>i.json.timezone_risk==='high').length;
const top=kept.slice(0,10);
let html='<h2>Daily Taiwan Eligible Async Remote Jobs</h2>';
html+=`<p><strong>Date:</strong> ${new Date().toLocaleDateString('en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Taipei'})}</p>`;
html+=`<p><strong>New jobs found:</strong> ${all.length} | <strong>Passed filters:</strong> ${kept.length} | <strong>Rejected:</strong> ${rejected.length}</p><hr/>`;
if(kept.length===0){html+='<p>No new qualifying jobs today. Keep grinding.</p>';}
else{
  html+='<h3>Top Jobs Today</h3>';
  top.forEach((item,idx)=>{
    const j=item.json;
    const alert=j.score>=85?'🔥 PRIORITY APPLY':'✅';
    html+=`<div style="border:1px solid #ddd;padding:12px;margin:8px 0;border-radius:6px"><p><strong>${idx+1}. ${alert} ${j.job_title||'Unknown'}</strong><br/>`;
    html+=`<strong>Company:</strong> ${j.company||'—'}<br/>`;
    html+=`<strong>Score:</strong> ${j.score}/100<br/>`;
    html+=`<strong>Taiwan eligible:</strong> ${j.taiwan_eligible||'unclear'} — ${j.taiwan_reason||'—'}<br/>`;
    html+=`<strong>Async level:</strong> ${j.async_level||'unknown'}<br/>`;
    html+=`<strong>Timezone risk:</strong> ${j.timezone_risk||'unknown'}<br/>`;
    html+=`<strong>Salary:</strong> ${j.salary||'Not listed'}<br/>`;
    html+=`<strong>Why it fits:</strong> ${j.why_good_fit||'—'}<br/>`;
    html+=`<strong>Source:</strong> ${j.source||'—'}<br/>`;
    html+=`<a href="${j.job_url||'#'}">Apply →</a></p></div>`;
  });
}
const manualCheck=kept.filter(i=>i.json.taiwan_eligible==='unclear'&&(i.json.score||0)>=75);
if(manualCheck.length){
  html+='<h3>Manual Check Needed</h3><ul>';
  manualCheck.forEach(i=>{html+=`<li><a href="${i.json.job_url}">${i.json.job_title} @ ${i.json.company}</a> — Score: ${i.json.score} — ${i.json.taiwan_reason}</li>`;});
  html+='</ul>';
}
html+=`<hr/><h3>Rejection Summary</h3><ul><li>Country-restricted or Taiwan ineligible: ${rejUS}</li><li>Hybrid/onsite: ${rejHybrid}</li><li>Timezone risk: ${rejTZ}</li><li>Score below 70: ${rejected.length-rejUS-rejHybrid-rejTZ}</li></ul>`;
return [{json:{digestHtml:html,keptCount:kept.length,totalCount:all.length}}];
